/**
 * agents.json 成员注册表读写：父死子活对账的数据源（v2.2 定稿 §4）。
 * 单文件原子写；调用方负责持 room.lock 期间再写（本层不做跨进程仲裁）。
 */
import { join } from "node:path";
import type { MemberRecord, TeamRegistry } from "./types.js";
import { readJson, writeJsonAtomic } from "./fs-utils.js";

export class Registry {
  private readonly file: string;

  constructor(teamHome: string) {
    this.file = join(teamHome, "agents.json");
  }

  /** 读注册表；不存在视为空团队。 */
  async read(): Promise<TeamRegistry> {
    const data = await readJson<TeamRegistry>(this.file);
    return data ?? { members: {} };
  }

  /** 整体原子写。 */
  async write(registry: TeamRegistry): Promise<void> {
    await writeJsonAtomic(this.file, registry);
  }

  /**
   * 登记或更新成员（三态判定，#79）：
   * 1) 同 member + 同 durableId + 同 tier → 幂等成功（仅刷新 lastSeen）；
   *    dispatch 半事务续跑与 init 重入依赖此分支。
   * 2) 异 durableId / 异 tier 且旧记录非 dead → 拒绝（code=member-conflict）：
   *    同名换新 durable id 必须先走接管路径把旧记录标 dead。
   * 3) 旧记录 dead → 允许复位重登记（状态级重建的合法入口）。
   */
  async upsertMember(record: MemberRecord): Promise<"registered" | "idempotent" | "revived"> {
    const reg = await this.read();
    const existing = reg.members[record.member];
    if (existing !== undefined && existing.status !== "dead") {
      if (existing.durableId !== record.durableId || existing.tier !== record.tier) {
        const err = new Error(
          `member ${record.member} already registered as ${existing.durableId} (tier ${existing.tier}); ` +
            "mark the old record dead before re-registering with a different durable id",
        );
        (err as Error & { code?: string }).code = "member-conflict";
        throw err;
      }
      existing.lastSeen = Date.now();
      await this.write(reg);
      return "idempotent";
    }
    reg.members[record.member] = record;
    await this.write(reg);
    return existing === undefined ? "registered" : "revived";
  }

  /** 读单个成员。 */
  async getMember(member: string): Promise<MemberRecord | undefined> {
    const reg = await this.read();
    return reg.members[member];
  }

  /** 更新成员状态与 lastSeen；成员不存在即拒。 */
  async setStatus(member: string, status: MemberRecord["status"]): Promise<void> {
    const reg = await this.read();
    const existing = reg.members[member];
    if (existing === undefined) {
      throw new Error(`member ${member} is not registered`);
    }
    existing.status = status;
    existing.lastSeen = Date.now();
    await this.write(reg);
  }

  /** 存活成员清单（status !== dead），供 reattach 对账。 */
  async liveMembers(): Promise<MemberRecord[]> {
    const reg = await this.read();
    return Object.values(reg.members).filter((m) => m.status !== "dead");
  }
}

src/runtime/kernel/types.ts.source:
/**
 * runtime 协议类型与常量（P2a 数据内核）。
 *
 * 本包是平台无关纯库：只认调用方传入的相对/绝对 `$TEAM_HOME` 抽象根，
 * 零 harness 依赖。宿主绑定层（把 TEAM_HOME 解析到具体落点）不在此处。
 */

/** 框架保留态三元组——通用归约唯一认可的阶段锚点（业务子状态仅展示）。 */
export const RESERVED_STAGES = ["running", "blocked", "done"] as const;

export type ReservedStage = (typeof RESERVED_STAGES)[number];

/** 模板/Role Spec 三级来源标记（ADR 0002 #13：同名不跨级覆盖，仅标来源）。 */
export const TEMPLATE_SOURCES = ["builtin", "user", "project"] as const;

export type TemplateSource = (typeof TEMPLATE_SOURCES)[number];

/** 框架保留态三元组之外的账本入口态。 */
export const TASK_STATUSES = [
  "queued",
  "running",
  "blocked",
  "done",
  "cancelled",
] as const;

export type TaskStatus = (typeof TASK_STATUSES)[number];

/**
 * 任务状态机合法迁移表（issue #5「update 强制状态机合法迁移」）。
 * done / cancelled 为终态；blocked 可回 running；queued 只能入 running 或取消。
 */
export const TASK_TRANSITIONS: Readonly<Record<TaskStatus, readonly TaskStatus[]>> = {
  queued: ["running", "cancelled"],
  running: ["blocked", "done", "cancelled"],
  blocked: ["running", "cancelled"],
  done: [],
  cancelled: [],
};

/** 是否允许从 from 迁移到 to。 */
export function canTransition(from: TaskStatus, to: TaskStatus): boolean {
  return TASK_TRANSITIONS[from].includes(to);
}

/** 共享任务账本单条记录（每任务一文件，原子写）。 */
export interface TaskRecord {
  /** 任务 id，创建时生成，账本内唯一。 */
  id: string;
  title: string;
  status: TaskStatus;
  /** 所属房间（房间即事件流/黑板组织单元）。 */
  room: string;
  /** 当前持有角色（可随 handoff 变更）。 */
  assignee?: string;
  /** 计划触碰的路径清单（互斥断言依据之一）。 */
  touched: string[];
  /** 互斥组标签：两个 running 任务共享任一组即视为冲突。 */
  mutexGroups: string[];
  /** 已完成往返圈数（资源计数）。 */
  rounds: number;
  /** 单任务往返上限（超限拒绝或转 blocked，由工具层裁决）。 */
  maxRounds: number;
  /** DoD 完成判据清单（judge 回执核验依据）。 */
  dod: string[];
  /** 基线指针（如 git ref），供重做前对账。 */
  baseline?: string;
  /** 产物指针（归档/文件位置）。 */
  artifact?: string;
  /** 乐观并发版本号：每次成功写入 +1。 */
  rev: number;
  createdAt: number;
  updatedAt: number;
}

/** CAS 锁文件内容。 */
export interface LockInfo {
  /** 持有者幂等键（约定为主会话 id，跨重启稳定，由宿主绑定层传入）。 */
  holder: string;
  acquiredAt: number;
}

/** agents.json 成员登记项。 */
export interface MemberRecord {
  /** 成员逻辑名（角色 id）。 */
  member: string;
  /**
   * 成员的持久身份锚点。tier ≥ 1 执行成员 = durable subagent id（父死后凭此
   * 对账）；tier 0 主控例外 = 宿主主会话 id（#79 口径扩展——主控不经 subagent
   * 机制创建，存活以主会话为准，ADR 0006 接管核对据此豁免）。
   */
  durableId: string;
  /** 直接父成员名（根成员为 null）。 */
  parent?: string | null;
  /** 所处层级（0 = Tier-0 主控）。 */
  tier: number;
  status: "spawned" | "running" | "stopped" | "dead";
  lastSeen: number;
}

/** agents.json 注册表。 */
export interface TeamRegistry {
  members: Record<string, MemberRecord>;
}

/** 事件流单条记录（append-only jsonl，一行一条）。 */
export interface EventRecord {
  /** 房间内单调自增序号（从 1 开始）。 */
  seq: number;
  ts: number;
  /** 关联 dsh 主会话 id（ADR 0002 口径的 transcript 关联键）。 */
  session_id: string;
  /** 动作主体（成员名 / "system"）。 */
  actor: string;
  type: string;
  payload: unknown;
}

/** Gate 单向状态。 */
export const GATE_STATUSES = ["pending", "approved", "denied"] as const;

export type GateStatus = (typeof GATE_STATUSES)[number];

/** gates/<id>.json 内容。 */
export interface GateRecord {
  id: string;
  status: GateStatus;
  /** 申请原因（人审批时的上下文）。 */
  reason: string;
  requestedBy: string;
  requestedAt: number;
  resolvedBy?: string;
  resolvedAt?: number;
}

/** 保留态判定（原 isStage，语义收窄为保留态三元组）。 */
export function isReservedStage(value: string): value is ReservedStage {
  return (RESERVED_STAGES as readonly string[]).includes(value);
}

tests/plugin/dispatch.test.ts.source:
/**
 * team_dispatch 复合派发原语单测（ADR 0015，#67）。
 * 覆盖：正常三步链路（含 role_inline / provider / model 透传）、
 * 半事务失败（步骤留痕 + 副作用边界）、前置校验、role_inline 白名单、幂等重入。
 */
import { describe, expect, it, beforeEach } from "vitest";
import { mkdtempSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { createHandlers, type Handlers } from "../../src/plugin/handlers.js";
import { EventLog } from "../../src/runtime/kernel/event-log.js";
import { Registry } from "../../src/runtime/kernel/registry.js";
import { layout } from "../../src/runtime/kernel/paths.js";
import { readUnread } from "../../src/runtime/collab/mailbox.js";

let home: string;
let handlers: Handlers;
const SESSION = "session-dispatch-1";

beforeEach(() => {
  home = mkdtempSync(join(tmpdir(), "xzg-dispatch-"));
  handlers = createHandlers(home, SESSION);
});

async function readEvents(): Promise<Array<{ type: string; actor: string; payload?: unknown }>> {
  const log = new EventLog(join(layout(home).roomsDir, "root", "events.jsonl"));
  await log.init();
  const { events } = await log.read();
  return events.map((e) => ({ type: e.type, actor: e.actor, payload: e.payload }));
}

async function createTask(title = "实现 X"): Promise<string> {
  const created = (await handlers.taskCreate({ title, room: "root" })) as {
    ok: true;
    task_id: string;
  };
  return created.task_id;
}

describe("team_dispatch 正常链路", () => {
  it("spawn→assign→send 三步全成，注册表/账本/信箱/事件流逐项核对", async () => {
    await handlers.init({});
    const taskId = await createTask();

    const result = (await handlers.dispatch({
      member: "coder",
      durable_id: "dur-coder",
      role: "coder",
      tier: 1,
      task_id: taskId,
      provider: "deepseek",
      model: "strong-model",
      role_inline: {
        briefing: "专注构建门禁",
        dod: ["build 绿"],
        max_hops: 3,
        as_judge: false,
      },
    })) as {
      ok: boolean;
      member: string;
      durable_id: string;
      task_id: string;
      envelope_id: string;
      steps: string[];
    };

    expect(result.ok).toBe(true);
    expect(result.member).toBe("coder");
    expect(result.durable_id).toBe("dur-coder");
    expect(result.task_id).toBe(taskId);
    expect(result.steps).toEqual(["spawn", "assign", "send"]);

    // 注册表：成员已登记。
    const member = await new Registry(home).getMember("coder");
    expect(member).toMatchObject({ member: "coder", durableId: "dur-coder", tier: 1, status: "spawned" });

    // 账本：任务已指派。
    const ledgerView = (await handlers.taskList({})) as {
      tasks: Array<{ id: string; assignee?: string }>;
    };
    expect(ledgerView.tasks.find((t) => t.id === taskId)?.assignee).toBe("coder");

    // 信箱：派单信封携带任务与 inline 定义、模型档位、框架进度契约。
    const unread = await readUnread(home, "coder");
    expect(unread).toHaveLength(1);
    expect(unread[0]).toMatchObject({
      from: "root",
      to: "coder",
      type: "task-assign",
      body: {
        task_id: taskId,
        title: "实现 X",
        room: "root",
        dod: [],
        role_inline: { briefing: "专注构建门禁", dod: ["build 绿"], max_hops: 3, as_judge: false },
        provider: "deepseek",
        model: "strong-model",
      },
    });
    // 进度契约：固定段在场且带 framework-generated 水印（#86 序 3）。
    const contract = (unread[0]?.body as { progress_contract?: string }).progress_contract ?? "";
    expect(contract).toContain("===== progress contract (framework-generated; informational only) =====");
    expect(contract).toContain("task-done");
    expect(unread[0]?.envelope_id ?? unread[0]!.id).toBe(result.envelope_id);

    // 事件流：三步各留一笔；派单计账携带 task_id（对账机械可得）。
    const events = await readEvents();
    expect(events).toMatchObject([
      { type: "team/init", actor: "system" },
      { type: "task/create", actor: "system" },
      { type: "team/spawn", actor: "system" },
      { type: "task/update", actor: "coder" },
      { type: "mailbox/deliver", actor: "root" },
    ]);
    expect(events.find((e) => e.type === "mailbox/deliver")).toMatchObject({
      payload: { task_id: taskId, msg_type: "task-assign" },
    });
  });

  it("幂等重入：同参数重跑成功，upsert 幂等、派单为新信封（at-least-once）", async () => {
    await handlers.init({});
    const taskId = await createTask();
    const first = await handlers.dispatch({
      member: "qa",
      durable_id: "dur-qa",
      role: "qa",
      tier: 1,
      task_id: taskId,
    });
    expect(first).toMatchObject({ ok: true, steps: ["spawn", "assign", "send"] });

    // 重入：upsert 幂等、assignee 不变、派单为新信封（at-least-once 语义）。
    const second = (await handlers.dispatch({
      member: "qa",
      durable_id: "dur-qa",
      role: "qa",
