/**
 * init 预登记 tier0 主控单测（#79 L1）。
 * 覆盖：主控入册（member=tiers[0].id、durableId=宿主会话 id、status=running）、
 * 返回值 master_member、team/init 事件载荷并入（不另发 spawn 事件）、
 * 同会话重入幂等、同名异 durableId 注册被拒（member-conflict）。
 */
import { describe, expect, it, beforeEach } from "vitest";
import { mkdtempSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { createHandlers, type Handlers } from "../../src/plugin/handlers.js";
import { Registry } from "../../src/runtime/kernel/registry.js";
import { EventLog } from "../../src/runtime/kernel/event-log.js";
import { layout } from "../../src/runtime/kernel/paths.js";

let home: string;
let handlers: Handlers;
const SESSION = "session-init-master-1";

beforeEach(() => {
  home = mkdtempSync(join(tmpdir(), "xzg-init-master-"));
  handlers = createHandlers(home, SESSION);
});

async function readEvents(): Promise<Array<{ type: string; payload: unknown }>> {
  const log = new EventLog(join(layout(home).roomsDir, "root", "events.jsonl"));
  await log.init();
  const { events } = await log.read();
  return events.map((e) => ({ type: e.type, payload: e.payload }));
}

describe("init 预登记 tier0 主控（#79）", () => {
  it("init 即入册：member=tiers[0].id、durableId=会话 id、status=running，返回 master_member", async () => {
    const result = (await handlers.init({})) as { ok: boolean; master_member?: string };
    expect(result.ok).toBe(true);
    // builtin 默认场景 oss-maintenance 的 tiers[0].id 即 "master"。
    expect(result.master_member).toBe("master");
    const master = await new Registry(home).getMember("master");
    expect(master).toMatchObject({
      tier: 0,
      parent: null,
      durableId: SESSION,
      status: "running",
    });
    // 并入 team/init 载荷，不另发 spawn 事件（保持事件类型序列契约稳定）。
    const events = await readEvents();
    expect(events.filter((e) => e.type === "team/spawn")).toHaveLength(0);
    expect(events[0]?.type).toBe("team/init");
    expect(events[0]?.payload).toMatchObject({ master: { member: "master", outcome: "registered" } });
  });

  it("同会话重入幂等：注册表仍单条 master，事件载荷 outcome=idempotent", async () => {
    await handlers.init({});
    await handlers.init({});
    const reg = await new Registry(home).read();
    expect(Object.keys(reg.members)).toEqual(["master"]);
    const events = await readEvents();
    const payloads = events.filter((e) => e.type === "team/init").map((e) => e.payload);
    expect(payloads[1]).toMatchObject({ master: { outcome: "idempotent" } });
  });

  it("同名异 durableId 注册被拒（member-conflict）；接管路径先标 dead 后可复位", async () => {
    await handlers.init({});
    await expect(
      handlers.spawn({ member: "master", durable_id: "dur-new", role: "master", tier: 1 }),
    ).rejects.toMatchObject({ code: "member-conflict" });
    // 模拟接管核对把旧记录标 dead 后，新身份即可入册。
    const registry = new Registry(home);
    await registry.setStatus("master", "dead");
    await expect(
      handlers.spawn({ member: "master", durable_id: "dur-new", role: "master", tier: 1 }),
    ).resolves.toMatchObject({ ok: true });
  });
});

tests/plugin/playbook-guard.test.ts.source:
/**
 * Tier-0 规程分层与组装守门（issue #42，增量 ADR 0009）。
 *
 * 三道闸：
 * 1. 分隔符格式锁定——分隔符是显式协议常量，改动即协议变更；
 * 2. 正向组装——init 返回值（HTTP 面经 /api/xiaozhuge/team/create，工具面已下线）
 *    = 规程全文 + 分隔符 + 场景 tiers[0].prompt，
 *   对任意场景成立（含单层 research-report，#39 依赖方）；
 * 3. 反向守门——内置模板场景 prompt 不得复制规程特征句，防双副本漂移复发。
 */
import { describe, expect, it, beforeEach } from "vitest";
import { existsSync, mkdtempSync, readFileSync, readdirSync } from "node:fs";
import { readFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { createHash } from "node:crypto";
import {
  assembleTier0Prompt,
  instantiateSnapshot,
  loadTemplate,
  loadTier0Playbook,
  PLAYBOOKS_DIR,
  TIER0_PLAYBOOK_FILE,
  TIER0_PLAYBOOK_SEPARATOR,
} from "../../src/index.js";
import { createHandlers, type Handlers } from "../../src/plugin/handlers.js";
import { appendToolManifest, TOOL_MANIFEST_SEPARATOR } from "../../src/plugin/tool-manifest.js";

const REPO_ROOT = join(fileURLToPath(new URL(".", import.meta.url)), "..", "..");
const OSS_DIR = join(REPO_ROOT, "templates", "oss-maintenance");
const RR_DIR = join(REPO_ROOT, "templates", "research-report");
const PLAYBOOK_PATH = join(REPO_ROOT, PLAYBOOKS_DIR, TIER0_PLAYBOOK_FILE);

/** 规程正文独有的特征句（框架协议知识，场景层不得复制）。 */
const PLAYBOOK_SIGNATURES = [
  "资源防护三项",
  "启动对账节",
  "状态级重建",
  "blocked_streak",
  "循环不变量",
  "目标锚定",
  "廉价检查轮",
  "防 max-tokens 解除武装",
];

describe("分隔符协议常量", () => {
  // 格式锁定：本断言变化 = 协议变更，须走增量 ADR。
  it("分隔符确切格式被锁定", () => {
    expect(TIER0_PLAYBOOK_SEPARATOR).toBe(
      "\n\n===== tier0 playbook / scenario prompt boundary =====\n\n",
    );
  });
});

describe("规程加载（playbooks/ 唯一事实源）", () => {
  it("全文读入且 digest 为源文件 sha256 前 16 位", () => {
    const playbook = loadTier0Playbook(REPO_ROOT);
    const raw = readFileSync(PLAYBOOK_PATH, "utf8");
    expect(playbook.text).toBe(raw);
    expect(playbook.digest).toBe(createHash("sha256").update(raw).digest("hex").slice(0, 16));
    expect(playbook.digest).toMatch(/^[0-9a-f]{16}$/);
  });

  it("规程文件随包存在于 playbooks/ 落点", () => {
    expect(existsSync(PLAYBOOK_PATH)).toBe(true);
    expect(existsSync(join(REPO_ROOT, "docs", "patrol", "tier0-playbook.md"))).toBe(false);
  });
});

describe("正向组装：tier0_prompt = 规程全文 + 分隔符 + 场景段", () => {
  let home: string;
  let handlers: Handlers;
  beforeEach(() => {
    home = mkdtempSync(join(tmpdir(), "xzg-pb-"));
    handlers = createHandlers(home, "session-playbook-1");
  });

  it("init 组装结果逐字节等于公式（ADR 0015：尾部追加工具面自述保留段），快照记录 playbook_digest", async () => {
    const result = (await handlers.init({})) as {
      tier0_prompt: string;
      playbook_digest: string;
    };
    const playbook = loadTier0Playbook(REPO_ROOT);
    const scenarioPrompt = readFileSync(join(OSS_DIR, "prompts", "master.md"), "utf8");
    expect(result.tier0_prompt).toBe(
      appendToolManifest(assembleTier0Prompt(playbook, scenarioPrompt)),
    );
    // 规程全文完整在场（#11 缺口不回潮）；保留段在规程与场景段之后
    expect(result.tier0_prompt).toContain(playbook.text);
    expect(result.tier0_prompt.indexOf(TOOL_MANIFEST_SEPARATOR)).toBeGreaterThan(
      result.tier0_prompt.indexOf(TIER0_PLAYBOOK_SEPARATOR),
    );
    expect(result.playbook_digest).toBe(playbook.digest);
    // 快照审计字段
    const snapshot = JSON.parse(await readFile(join(home, "team.yaml"), "utf8")) as {
      playbook_digest?: string;
    };
    expect(snapshot.playbook_digest).toBe(playbook.digest);
  });

  it("research-report（单层场景）经同一组装公式同样获得规程全文（#39 依赖）", async () => {
    const loaded = await loadTemplate(RR_DIR, "builtin");
    const playbook = loadTier0Playbook(REPO_ROOT);
    const scenarioPrompt = loaded.prompts["./prompts/master.md"] ?? "";
    const assembled = assembleTier0Prompt(playbook, scenarioPrompt);
    expect(scenarioPrompt.length).toBeGreaterThan(0);
    expect(assembled).toContain(playbook.text);
    expect(assembled.indexOf(playbook.text)).toBeLessThan(assembled.indexOf(TIER0_PLAYBOOK_SEPARATOR));
  });

  it("旧口径兼容：instantiateSnapshot 不传 digest 时快照字段为 null", async () => {
    const loaded = await loadTemplate(OSS_DIR, "builtin");
    const snapshot = instantiateSnapshot(loaded) as { playbook_digest: unknown };
    expect(snapshot.playbook_digest).toBeNull();
  });
});

describe("反向守门：内置模板场景 prompt 不得复制规程特征句", () => {
  it("templates/*/prompts/*.md 全量扫描零命中", () => {
    const templatesDir = join(REPO_ROOT, "templates");
    for (const scenario of readdirSync(templatesDir)) {
      const promptsDir = join(templatesDir, scenario, "prompts");
      if (!existsSync(promptsDir)) continue;
      for (const file of readdirSync(promptsDir)) {
        const content = readFileSync(join(promptsDir, file), "utf8");
        for (const sig of PLAYBOOK_SIGNATURES) {
          expect(content.includes(sig), `${scenario}/prompts/${file} 含规程特征句「${sig}」`).toBe(false);
        }
      }
    }
  });

  it("特征句清单本身仍全部命中现行规程（防守门空转）", () => {
    const playbookText = readFileSync(PLAYBOOK_PATH, "utf8");
    for (const sig of PLAYBOOK_SIGNATURES) {
      expect(playbookText.includes(sig), `特征句「${sig}」已不在规程中，须更新清单`).toBe(true);
    }
  });
});

tests/plugin/reconcile.test.ts.source:
/**
 * team_reconcile 对账原语单测（ADR 0015 决策 1，#66）。
 * 覆盖：overview 全量视图（成员对照 / 悬空指派 / 状态分布 / 事件游标 /
 * goal 占位）、scope=audit 旁路 report-only（未登记文件 / 过期登记 /
 * 敏感名掩码 / 无工作区不可用）、参数校验。
 */
import { describe, expect, it, beforeEach } from "vitest";
import { mkdirSync, mkdtempSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { createHandlers, type Handlers } from "../../src/plugin/handlers.js";

let home: string;
let handlers: Handlers;
let workspace: string;
const SESSION = "session-reconcile-1";

beforeEach(() => {
  home = mkdtempSync(join(tmpdir(), "xzg-rec-home-"));
  workspace = mkdtempSync(join(tmpdir(), "xzg-rec-ws-"));
  handlers = createHandlers(home, SESSION);
});

describe("team_reconcile overview", () => {
  it("一次调用返回快照摘要、成员对照、状态分布、事件游标与 goal 占位", async () => {
    await handlers.init({ project_root: workspace });
    await handlers.spawn({ member: "coder", durable_id: "dur-coder", role: "coder", tier: 1 });
    const t = (await handlers.taskCreate({
      title: "实现 X",
      room: "root",
      assignee: "coder",
      touched_paths: ["src/a.ts"],
    })) as { task_id: string };
    // 悬空指派：账本有 assignee、注册表无此成员。
    await handlers.taskUpdate({ task_id: t.task_id, assignee: "ghost" });

    const view = (await handlers.reconcile({})) as {
      ok: boolean;
      scope: string;
      initialized: boolean;
      snapshot: { source: string | null; workspace_seen?: unknown };
      members: Array<{ member: string; liveness: string; assigned_task_ids: string[] }>;
      dangling_assignees: string[];
      orphan_members: Array<{ member: string; tier: number; parent: string | null; reason: string }>;
      task_status_counts: Record<string, number>;
      event_cursors: Array<{ room: string; seq: number }>;
      goal_binding: string;
      tool_manifest_pointer: string;
    };

    expect(view.ok).toBe(true);
    expect(view.scope).toBe("overview");
    expect(view.initialized).toBe(true);
    expect(view.snapshot?.source).toBe("builtin");
    expect(view.members).toHaveLength(2);
    // init 预登记的 tier0 主控（#79）：durableId = 宿主会话 id，对账可见。
    expect(view.members.find((m) => m.member === "master")).toMatchObject({
      durable_id: SESSION,
      liveness: "framework-invisible",
    });
    expect(view.members.find((m) => m.member === "coder")).toMatchObject({
      member: "coder",
      durable_id: "dur-coder",
      liveness: "framework-invisible",
    });
    expect(view.dangling_assignees).toEqual(["ghost"]);
    // 孤儿标红（report-only）：spawn 未传 parent → coder 标 parent-missing；
    // tier0 主控豁免（单入口原则）。
    expect(view.orphan_members).toEqual([
      { member: "coder", tier: 1, parent: null, reason: "parent-missing" },
    ]);
    expect(view.task_status_counts).toEqual({ queued: 1 });
    expect(view.event_cursors[0]?.room).toBe("root");
    expect(view.event_cursors[0]!.seq).toBeGreaterThan(0);
    expect(view.goal_binding).toContain("framework-invisible");
    expect(view.goal_binding).toContain("get_goal");
    expect(view.tool_manifest_pointer).toContain("tool manifest");
  });

  it("未初始化实例返回 initialized=false 且不抛错", async () => {
    const view = (await handlers.reconcile({})) as { initialized: boolean; snapshot: unknown };
    expect(view.initialized).toBe(false);
    expect(view.snapshot).toBeNull();
  });

  it("孤儿标红：有 parent 且在册不标；悬空 parent 标 parent-dangling", async () => {
    await handlers.init({ project_root: workspace });
    // coder 带合法 parent（master 由 init 预登记）→ 不标。
    await handlers.spawn({
      member: "coder",
      durable_id: "dur-coder",
      role: "coder",
      tier: 1,
      parent: "master",
    });
    // painter 的 parent 未注册 → 标 parent-dangling。
    await handlers.spawn({
      member: "painter",
      durable_id: "dur-painter",
      role: "painter",
      tier: 1,
      parent: "ghost-parent",
    });

    const view = (await handlers.reconcile({})) as {
      orphan_members: Array<{ member: string; tier: number; parent: string | null; reason: string }>;
    };
    expect(view.orphan_members).toEqual([
      { member: "painter", tier: 1, parent: "ghost-parent", reason: "parent-dangling" },
    ]);
  });
});

describe("team_reconcile scope=audit", () => {
  it("双向 diff：未登记文件命中、登记在案不误报、过期登记入 stale", async () => {
    // 工作树：src/a.ts（将登记）+ build.log（不登记）。
    mkdirSync(join(workspace, "src"), { recursive: true });
    writeFileSync(join(workspace, "src", "a.ts"), "export {};\n");
    writeFileSync(join(workspace, "build.log"), "noise\n");

    await handlers.init({ project_root: workspace });
    await handlers.taskCreate({
      title: "T",
      room: "root",
      touched_paths: ["src/a.ts", "gone/missing.ts"],
    });

    const view = (await handlers.reconcile({ scope: "audit" })) as {
      audit: {
        available: boolean;
        scanned_root: string;
        unregistered_files: Array<{ path: string; size: number; sensitive_masked: boolean }>;
        stale_registered_paths: string[];
        truncated: boolean;
      };
    };

    expect(view.audit.available).toBe(true);
    expect(view.audit.scanned_root).toBe(workspace);
    const paths = view.audit.unregistered_files.map((f) => f.path);
    expect(paths).toContain("build.log");
    expect(paths).not.toContain(join("src", "a.ts"));
    expect(view.audit.stale_registered_paths).toEqual(["gone/missing.ts"]);
    expect(view.audit.truncated).toBe(false);
    // 元数据形态：size/mtime 为数值，绝无内容字段。
    const f = view.audit.unregistered_files.find((x) => x.path === "build.log")!;
    expect(typeof f.size).toBe("number");
    expect(f.sensitive_masked).toBe(false);
    expect(Object.keys(f)).not.toContain("content");
  });

  it("敏感文件名打掩码，完整名不外泄", async () => {
    writeFileSync(join(workspace, ".env.local"), "SECRET=1\n");
    await handlers.init({ project_root: workspace });
    const view = (await handlers.reconcile({ scope: "audit" })) as {
      audit: { unregistered_files: Array<{ path: string; sensitive_masked: boolean }> };
    };
    const masked = view.audit.unregistered_files.find((f) => f.sensitive_masked);
    expect(masked).toBeDefined();
    expect(masked!.path).not.toContain(".env.local");
    expect(masked!.path.endsWith("<masked:sensitive-name>")).toBe(true);
  });

  it("旧快照无 workspace 字段 → 审计诚实标注不可用", async () => {
    await handlers.init({});
    const view = (await handlers.reconcile({ scope: "audit" })) as {
      audit: { available: boolean; reason: string };
    };
    expect(view.audit.available).toBe(false);
    expect(view.audit.reason).toContain("audit unavailable");
  });
});

describe("team_reconcile 参数校验", () => {
  it("非法 scope 拒绝", async () => {
    await handlers.init({});
    await expect(handlers.reconcile({ scope: "everything" })).rejects.toMatchObject({
      code: "invalid-arguments",
    });
  });
});

tests/plugin/team-launch.test.ts.source:
/**
 * Team 拉起入口 HTTP 面测试（#51）：scenarios 枚举、create 一键建团
 * （默认/指定场景、unknown-scenario 稳定错误码、双头断言）、status 探测、
 * 入口页直出。node:http 真实监听回环端口驱动 WebRoute。
 */
import { describe, expect, it, beforeEach } from "vitest";
import { mkdirSync, mkdtempSync, readFileSync, writeFileSync } from "node:fs";
import { readFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { createServer } from "node:http";
import { join } from "node:path";
import {
  bootMessage,
  launchPageHtml,
  makeLaunchRoutes,
} from "../../src/plugin/team-launch.js";

let home: string;

beforeEach(() => {
  home = mkdtempSync(join(tmpdir(), "xzg-launch-"));
  process.env.DSH_HOME = join(home, "dsh-home");
});

/** 构造一个可通过加载校验的最小场景模板（team.yaml + roles + prompts）。 */
function makeScenario(root: string, name: string): void {
  const dir = join(root, name);
  mkdirSync(join(dir, "roles"), { recursive: true });
  mkdirSync(join(dir, "prompts"), { recursive: true });
  writeFileSync(join(dir, "prompts", "master.md"), `# ${name} master\n`);
  writeFileSync(join(dir, "prompts", "worker.md"), `# ${name} worker\n`);
  writeFileSync(
    join(dir, "team.yaml"),
    JSON.stringify({
      name,
      version: 1,
      tiers: [
        { id: "master", prompt: "./prompts/master.md" },
        { id: "worker", prompt: "./prompts/worker.md" },
      ],
      roles: ["master", "worker", "qa"],
    }),
  );
  writeFileSync(
    join(dir, "roles", "master.role.yaml"),
    JSON.stringify({ id: "master", prompt: "./prompts/master.md", dod: ["d"] }),
  );
  writeFileSync(
    join(dir, "roles", "worker.role.yaml"),
    JSON.stringify({ id: "worker", prompt: "./prompts/worker.md", dod: ["d"] }),
  );
  writeFileSync(
    join(dir, "roles", "qa.role.yaml"),
    JSON.stringify({ id: "qa", prompt: "./prompts/worker.md", as_judge: true, dod: ["d"] }),
  );
}

/** user 层模板根（DSH_HOME 在 beforeEach 隔离）。 */
function userTplRoot(): string {
  return join(home, "dsh-home", "xiaozhuge", "templates");
}

async function listen(): Promise<string> {
  const routes = makeLaunchRoutes();
  const server = createServer((req, res) => {
    const url = new URL(req.url ?? "/", `http://${req.headers.host}`);
    for (const route of routes) {
      if (route.kind === "exact" && route.path === url.pathname) {
        void route.handler(req, res);
        return;
      }
    }
    res.writeHead(404);
    res.end();
  });
  await new Promise<void>((resolve) => server.listen(0, "127.0.0.1", resolve));
  return `http://127.0.0.1:${(server.address() as { port: number }).port}`;
}

function jsonHeaders(base: string): Record<string, string> {
  return { "content-type": "application/json", origin: base };
}

async function post(
  base: string,
  body: unknown,
  headers: Record<string, string> = jsonHeaders(base),
): Promise<{ status: number; json: any }> {
  const r = await fetch(`${base}/api/xiaozhuge/team/create`, {
    method: "POST",
    headers,
    body: JSON.stringify(body),
  });
  return { status: r.status, json: await r.json() };
}

describe("场景枚举", () => {
  it("列出全部 builtin 场景（oss-maintenance + research-report）带 source 标记", async () => {
    const base = await listen();
    const r = await fetch(`${base}/api/xiaozhuge/team/scenarios`);
    const data = (await r.json()) as { scenarios: Array<{ name: string; source: string }> };
    expect(data.scenarios).toEqual([
      { name: "oss-maintenance", source: "builtin" },
      { name: "research-report", source: "builtin" },
    ]);
  });

  it("scenarios 端点接受 workspace 参数（包含 project 层）", async () => {
    const base = await listen();
    // 带 workspace 参数但无 project 模板 → 仍只有 builtin
    const r = await fetch(`${base}/api/xiaozhuge/team/scenarios?workspace=${encodeURIComponent(home)}`);
    const data = (await r.json()) as { scenarios: Array<{ name: string; source: string }> };
    const builtin = data.scenarios.filter((s) => s.source === "builtin").length;
    expect(builtin).toBeGreaterThan(0);
  });
});

describe("team/create 一键建团", () => {
  it("默认场景：init 持久化 + tier0_prompt 组装 + 快照落盘", async () => {
    const base = await listen();
    const { status, json } = await post(base, { session: "s-default" });
    expect(status).toBe(200);
    expect(json.ok).toBe(true);
    expect(json.scenario).toBe("oss-maintenance");
    expect(json.tier0_prompt).toContain("资源防护三项");
    expect(json.tier0_prompt).toContain("tier0 playbook / scenario prompt boundary");
    expect(json.tier0_prompt).toContain("一级主控场景编排");
    expect(json.playbook_digest).toMatch(/^[0-9a-f]{16}$/);
    // 实例根持久化
    const snap = JSON.parse(
      await readFile(join(home, "dsh-home", "xiaozhuge", "sessions", "s-default", "team.yaml"), "utf8"),
    ) as { name: string; playbook_digest?: string };
    expect(snap.name).toBe("oss-maintenance");
    expect(snap.playbook_digest).toBe(json.playbook_digest);
  });

  it("research-report 场景：实例化后 tier0_prompt 含规程全文（#39 依赖）", async () => {
    const base = await listen();
    const { status, json } = await post(base, { session: "s-rr", scenario: "research-report" });
    expect(status).toBe(200);
    expect(json.scenario).toBe("research-report");
    expect(json.tier0_prompt).toContain("Tier-0 巡场规程");
    expect(json.tier0_prompt).toContain("唯一主控");
  });

  it("未知场景给稳定错误码 unknown-scenario（HTTP 400）", async () => {
    const base = await listen();
    for (const bad of ["no-such-template", "../escape", "OSS"]) {
      const { status, json } = await post(base, { session: "s-bad", scenario: bad });
      expect(status, bad).toBe(400);
      expect((json.error as { code: string }).code, bad).toBe("unknown-scenario");
    }
  });

  it("缺 session 参数 400；无 Origin POST 403；SFS 跨站 403", async () => {
    const base = await listen();
    const noSession = await post(base, {});
    expect(noSession.status).toBe(400);
    const noOrigin = await post(base, { session: "s" }, { "content-type": "application/json" });
    expect(noOrigin.status).toBe(403);
    const crossSite = await post(
      base,
      { session: "s" },
      { ...jsonHeaders(base), "sec-fetch-site": "cross-site" },
    );
    expect(crossSite.status).toBe(403);
  });

  it("同会话重入 reentered（幂等不变），异会话独立实例根", async () => {
    const base = await listen();
    const first = await post(base, { session: "s-re" });
    expect(first.json.lock).toBe("acquired");
    const again = await post(base, { session: "s-re" });
    expect(again.json.lock).toBe("reentered");
    const other = await post(base, { session: "s-other" });
    expect(other.json.home).not.toBe(first.json.home);
  });

  it("user 层模板经 source=user 实例化，返回携带 source 标记", async () => {
    makeScenario(userTplRoot(), "my-scenario");
    const base = await listen();
    const { status, json } = await post(base, { session: "s-user", scenario: "my-scenario", source: "user" });
    expect(status).toBe(200);
    expect(json.source).toBe("user");
    expect(json.scenario).toBe("my-scenario");
  });

  it("user 层唯一场景（无同名）可不指定 source 正常命中", async () => {
    makeScenario(userTplRoot(), "unique-scenario");
    const base = await listen();
    const { status, json } = await post(base, { session: "s-unique", scenario: "unique-scenario" });
    expect(status).toBe(200);
    expect(json.source).toBe("user");
    expect(json.scenario).toBe("unique-scenario");
  });

  it("同名场景（user+project）未指定 source → ambiguous-scenario（HTTP 400）", async () => {
    makeScenario(userTplRoot(), "dup");
    const projectRoot = join(home, "project-repo");
    mkdirSync(join(projectRoot, ".xiaozhuge", "templates"), { recursive: true });
    makeScenario(join(projectRoot, ".xiaozhuge", "templates"), "dup");
    const base = await listen();
    const { status, json } = await post(base, {
      session: "s-amb",
      scenario: "dup",
      workspace: projectRoot,
    });
    expect(status).toBe(400);
    expect(json.error.code).toBe("ambiguous-scenario");
  });

  it("同名场景指定 source 消歧：project 层命中", async () => {
    makeScenario(userTplRoot(), "dup");
    const projectRoot = join(home, "project-repo2");
    mkdirSync(join(projectRoot, ".xiaozhuge", "templates"), { recursive: true });
    makeScenario(join(projectRoot, ".xiaozhuge", "templates"), "dup");
    const base = await listen();
    const { status, json } = await post(base, {
      session: "s-proj",
      scenario: "dup",
      source: "project",
      workspace: projectRoot,
    });
    expect(status).toBe(200);
    expect(json.source).toBe("project");
    expect(json.scenario).toBe("dup");
  });
});

